<pre>
   var client = algoliasearch('UIXXXXXX', '1241342342352524');
    var index = client.initIndex('CATEGORIES');
    setTimeout(autocompleteCategories, 250);
function autocompleteCategories() {
        $('#autocomplete-categories').autocomplete({ autoselect: true, openOnFocus: true, hint: false, minLength: 2 }, [
            {
              source: function(q, cb) {
                index.search(q, { hitsPerPage: 10 }, function(error, content) {
                  if (error) {
                    cb([]);
                    return;
                  }
                  cb(content.hits, content);
                });
              },
              displayKey: 'name',
              templates: {
                suggestion: function(suggestion) {
                  return suggestion._highlightResult.name.value;
                }
              }
            }
          ]).on('autocomplete:selected', function(event, suggestion, dataset) {
            console.log(suggestion, dataset);
 // here, not sure which client variable should be refered to ?
            var helper = algoliasearchHelper( client, 'COMPANIES_production', {
                disjunctiveFacets: ['ORcategories']
            });
            helper.setQuery(suggestion.name).addDisjunctiveFacetRefinement('ORcategories');
            helper.search();
            helper.on('result', function(results) { updateUI(results); });
          });
